import {
  Msg$TitleSaved as titleSaved,
  Msg$TitleSaveFailed as titleSaveFailed,
} from './app.mjs'

export const saveTitle = title => ({
  perform: () => localStorage.setItem('title', title),
  onSuccess: () => titleSaved(),
  onFailure: () => titleSaveFailed(),
})

export const log = message => ({
  perform: () => console.log(message),
})

subscription.source:
export function every(milliseconds, handleTick) {
  return {
    start: emit => {
      const timer = setInterval(() => emit(handleTick(Date.now())), milliseconds)
      return () => clearInterval(timer)
    },
  }
}

