// @ts-check
import { html, render } from 'lit-html'
import { Model$Model$title as title, UserChangedTitle } from './app.mjs'

/** @typedef {import('./app.mjs').Model$} Model */
/** @typedef {import('./app.mjs').Msg$} Msg */

/** @param {Model} model @param {(message: Msg) => void} dispatch */
export function view(model, dispatch) {
  const mount = document.getElementById('app')
  if (!mount) throw new Error('Missing #app mount element')

  render(html`
    <h1>${title(model)}</h1>
    <button @click=${() => dispatch(new UserChangedTitle('Hello'))}>
      Reset title
    </button>
  `, mount)
}

